private string BuildStudentFullNameCellHtml(DataRow drw)
{
    string strFirst = Convert.ToString(drw["StudentFirstName"]);
    string strLast = Convert.ToString(drw["StudentLastName"]);
    if (strFirst == null)
        strFirst = "";
    if (strLast == null)
        strLast = "";
    strFirst = strFirst.Trim();
    strLast = strLast.Trim();
    string strFull = strFirst;
    if (strLast.Length > 0)
    {
        if (strFull.Length > 0)
            strFull = strFull + " " + strLast;
        else
            strFull = strLast;
    }
    return "<td class='col-name'>" + HtmlEncodeText(strFull) + "</td>";
}

